insert into public.sources (id, source_key, title, kind, url, show_by_default) values ('00000000-0000-4000-8000-000000000001', 'shimamotor-acro-level-test', '島本アクロレッスン レベルテスト', 'pdf', 'https://www.dropbox.com/scl/fi/5efdb2q2boi3ripstgymy/.pdf?rlkey=0gt6arv6rv5srkidk21y0u7ev&st=bszy3coz&e=1&dl=0', false) on conflict (source_key) do nothing;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000002', 't002', '前回り受け身', array[]::text[], 'ダブルダッチ / 基礎ムーブの最初に固めたい基礎技。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。', '前回り受け身は、ダブルダッチの要素を持つ基礎ムーブ系の技です。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。レベル1「倒立系」では「記載技をすべてクリア」が目安です。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。 ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。 前提技・派生技・近い技は相関図で確認できます。', '前回り受け身の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。', array['縄なしで足順とリズムを確認する', '低速の縄で入る位置と抜ける位置を固定する', '音楽テンポでも姿勢が崩れないか確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。基礎ムーブ系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 1, 1, 'ダブルダッチ', '基礎ムーブ', '移動・切り返し', 'その場', '足立ち', '縄内アップ', array['ダブルダッチ', '基礎ムーブ', 'Lv.1'], 1, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000003', 't003', '首抜き後転', array[]::text[], '体操 / 倒立・床基礎の最初に固めたい基礎技。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。', '首抜き後転は、体操の要素を持つ倒立・床基礎系の技です。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。レベル1「倒立系」では「記載技をすべてクリア」が目安です。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '首抜き後転の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。', array['マット上で形と受け身を確認する', '肩と体幹を締めたまま静止または移動する', '縄内では入る前後の姿勢までセットで練習する'], array['肩が抜けて腰が反る', '手を着く位置が近すぎて受け身が狭くなる'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。倒立・床基礎系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 1, 1, '体操', '倒立・床基礎', '移動・切り返し', 'その場', '足立ち', '縄内アップ', array['体操', '倒立・床基礎', 'Lv.1'], 1, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000004', 't004', 'フロントスウィープ', array[]::text[], 'ダブルダッチ / 基礎ムーブの最初に固めたい基礎技。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。', 'フロントスウィープは、ダブルダッチの要素を持つ基礎ムーブ系の技です。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。レベル1「倒立系」では「記載技をすべてクリア」が目安です。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。 ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。 前提技・派生技・近い技は相関図で確認できます。', 'フロントスウィープの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。', array['縄なしで足順とリズムを確認する', '低速の縄で入る位置と抜ける位置を固定する', '音楽テンポでも姿勢が崩れないか確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。基礎ムーブ系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 1, 1, 'ダブルダッチ', '基礎ムーブ', '移動・切り返し', '助走・反発', '足立ち', '縄内アップ', array['ダブルダッチ', '基礎ムーブ', 'Lv.1'], 1, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
