insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000010', 't010-j', 'スイング（Jステップ）', array[]::text[], 'ダブルダッチ / 基礎ムーブの最初に固めたい基礎技。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。', 'スイング（Jステップ）は、ダブルダッチの要素を持つ基礎ムーブ系の技です。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。レベル1「倒立系」では「記載技をすべてクリア」が目安です。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。 ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。 前提技・派生技・近い技は相関図で確認できます。', 'スイング（Jステップ）の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。', array['縄なしで足順とリズムを確認する', '低速の縄で入る位置と抜ける位置を固定する', '音楽テンポでも姿勢が崩れないか確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。基礎ムーブ系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 1, 1, 'ダブルダッチ', '基礎ムーブ', '移動・切り返し', 'その場', '足立ち', '縄内アップ', array['ダブルダッチ', '基礎ムーブ', 'Lv.1'], 1, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
