insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000020', 't020', 'プッシュアップ', array[]::text[], '体操 / 倒立・床基礎の最初に固めたい基礎技。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。', 'プッシュアップは、体操の要素を持つ倒立・床基礎系の技です。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。レベル2「倒立系」では「記載技をすべてクリア」が目安です。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', 'プッシュアップの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。', array['マット上で形と受け身を確認する', '肩と体幹を締めたまま静止または移動する', '縄内では入る前後の姿勢までセットで練習する'], array['肩が抜けて腰が反る', '手を着く位置が近すぎて受け身が狭くなる'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。倒立・床基礎系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 2, 1, '体操', '倒立・床基礎', '移動・切り返し', '手支持・床支持', '足立ち', '縄内アップ', array['体操', '倒立・床基礎', 'Lv.2'], 2, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000021', 't021', 'ベビースワイプ', array[]::text[], 'ブレイキン / ブレイキン・床回転の最初に固めたい基礎技。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。', 'ベビースワイプは、ブレイキンの要素を持つブレイキン・床回転系の技です。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。レベル2「倒立系」では「記載技をすべてクリア」が目安です。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。 ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。 前提技・派生技・近い技は相関図で確認できます。', 'ベビースワイプの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。ブレイキン・床回転系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 2, 1, 'ブレイキン', 'ブレイキン・床回転', '床回転', '手支持・床支持', '足立ち', '縄内アップ', array['ブレイキン', 'ブレイキン・床回転', 'Lv.2'], 2, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
