insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000025', 't025--to-', '前方ブリッジ→起き上がり', array[]::text[], '体操 / 倒立・床基礎の発展技へ進むための中核技。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。', '前方ブリッジ→起き上がりは、体操の要素を持つ倒立・床基礎系の技です。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。レベル3「倒立系」では「記載技をすべてクリア」が目安です。肩、体幹、受け身を整え、手支持や床支持の姿勢を崩さないことが重要です。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '前方ブリッジ→起き上がりの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。手支持、受け身、肩の押し、体幹の締めを作る系統です。空中技に進む前に、床で体を支える感覚をそろえます。', array['マット上で形と受け身を確認する', '肩と体幹を締めたまま静止または移動する', '縄内では入る前後の姿勢までセットで練習する'], array['肩が抜けて腰が反る', '手を着く位置が近すぎて受け身が狭くなる'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。倒立・床基礎系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 2, 2, '体操', '倒立・床基礎', '移動・切り返し', 'その場', '足立ち', '縄内単発', array['体操', '倒立・床基礎', 'Lv.3'], 3, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
