insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000036', 't036', '片手側転', array[]::text[], '体操 / 側方・反発の発展技へ進むための中核技。手を着く位置、腰の通り道、着地後の反発をそろえると次の空中技へつながります。', '片手側転は、体操の要素を持つ側方・反発系の技です。側転、ロンダート、バク転など、床を押して次の技へ反発を残す系統です。助走と着地後の進行方向が学習の鍵になります。レベル3「倒立系」では「記載技をすべてクリア」が目安です。手を着く位置、腰の通り道、着地後の反発をそろえると次の空中技へつながります。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '片手側転の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。側転、ロンダート、バク転など、床を押して次の技へ反発を残す系統です。助走と着地後の進行方向が学習の鍵になります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。側方・反発系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 2, 2, '体操', '側方・反発', '縦・横回転', 'その場', '足立ち', '縄内単発', array['体操', '側方・反発', 'Lv.3'], 3, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source