insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000052', 't052', '側宙', array[]::text[], '体操 / 空中回転の発展技へ進むための中核技。踏切の高さ、回転姿勢、着地の向きを分けて確認しながら段階的に練習します。', '側宙は、体操の要素を持つ空中回転系の技です。踏切で高さを作り、空中で姿勢をまとめ、着地でほどく系統です。縄内では回転そのものより入るタイミングと抜ける余白が重要です。レベル5「倒立系」では「記載技をすべてクリア」が目安です。踏切の高さ、回転姿勢、着地の向きを分けて確認しながら段階的に練習します。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '側宙の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。踏切で高さを作り、空中で姿勢をまとめ、着地でほどく系統です。縄内では回転そのものより入るタイミングと抜ける余白が重要です。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['痛みがある日は無理に通さない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。空中回転系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, '体操', '空中回転', '縦・横回転', '助走・反発', '足立ち', '縄内単発', array['体操', '空中回転', 'Lv.5'], 5, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000053', 't053', 'バク転', array[]::text[], '体操 / 側方・反発の発展技へ進むための中核技。手を着く位置、腰の通り道、着地後の反発をそろえると次の空中技へつながります。', 'バク転は、体操の要素を持つ側方・反発系の技です。側転、ロンダート、バク転など、床を押して次の技へ反発を残す系統です。助走と着地後の進行方向が学習の鍵になります。レベル5「倒立系」では「記載技をすべてクリア」が目安です。手を着く位置、腰の通り道、着地後の反発をそろえると次の空中技へつながります。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', 'バク転の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。側転、ロンダート、バク転など、床を押して次の技へ反発を残す系統です。助走と着地後の進行方向が学習の鍵になります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。側方・反発系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, '体操', '側方・反発', '移動・切り返し', '助走・反発', '足立ち', '縄内単発', array['体操', '側方・反発', 'Lv.5'], 5, '倒立系', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000054', 't054', 'バックドンキー', array[]::text[], 'ダブルダッチ / 基礎ムーブの演技に入れやすい発展技。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。', 'バックドンキーは、ダブルダッチの要素を持つ基礎ムーブ系の技です。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。縄のリズムを崩さず、踏み替えや床移動を安定させることが練習の軸になります。 ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。 前提技・派生技・近い技は相関図で確認できます。', 'バックドンキーの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ダブルダッチ由来の動きは、ロープの周期、ターンとの距離、音楽への乗せ方まで含めて技になります。縄の中で崩れない足順、低い姿勢、床移動を作る系統です。派手さよりもリズムの継続と入退場の安定が価値になります。', array['縄なしで足順とリズムを確認する', '低速の縄で入る位置と抜ける位置を固定する', '音楽テンポでも姿勢が崩れないか確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。基礎ムーブ系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, 'ダブルダッチ', '基礎ムーブ', '移動・切り返し', 'その場', '足立ち', '縄内単発', array['ダブルダッチ', '基礎ムーブ', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
