insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000060', 't060', '側転ツイスト', array[]::text[], '体操 / ひねりの演技に入れやすい発展技。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。', '側転ツイストは、体操の要素を持つひねり系の技です。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '側転ツイストの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['痛みがある日は無理に通さない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。ひねり系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, '体操', 'ひねり', 'ひねり軸', 'その場', '足立ち', '縄内単発', array['体操', 'ひねり', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000061', 't061', 'エアツイガンビ', array[]::text[], 'カポエイラ / トリッキングの演技に入れやすい発展技。手支持と蹴り上げの軌道を滑らかにつなぎ、勢いを止めずに切り返します。', 'エアツイガンビは、カポエイラの要素を持つトリッキング系の技です。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。手支持と蹴り上げの軌道を滑らかにつなぎ、勢いを止めずに切り返します。 カポエイラ由来の動きは、蹴り上げ、片手支持、流れる切り返しが特徴です。縄内では動線を止めずに戻れるかを見ます。 前提技・派生技・近い技は相関図で確認できます。', 'エアツイガンビの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。カポエイラ由来の動きは、蹴り上げ、片手支持、流れる切り返しが特徴です。縄内では動線を止めずに戻れるかを見ます。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。トリッキング系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, 'カポエイラ', 'トリッキング', '移動・切り返し', 'その場', '足立ち', '縄内単発', array['カポエイラ', 'トリッキング', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000062', 't062-540', '540', array[]::text[], 'トリッキング / トリッキングの演技に入れやすい発展技。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。', '540は、トリッキングの要素を持つトリッキング系の技です。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', '540の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。トリッキング系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, 'トリッキング', 'トリッキング', '移動・切り返し', '片足', '足立ち', '縄内単発', array['トリッキング', 'トリッキング', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000063', 't063', 'サイドスワイプ', array[]::text[], 'ブレイキン / ブレイキン・床回転の演技に入れやすい発展技。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。', 'サイドスワイプは、ブレイキンの要素を持つブレイキン・床回転系の技です。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。 ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。 前提技・派生技・近い技は相関図で確認できます。', 'サイドスワイプの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。ブレイキン・床回転系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, 'ブレイキン', 'ブレイキン・床回転', '床回転', '手支持・床支持', '足立ち', '縄内単発', array['ブレイキン', 'ブレイキン・床回転', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
