insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000069', 't069', 'コインドロップ', array[]::text[], 'ブレイキン / ブレイキン・床回転の演技に入れやすい発展技。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。', 'コインドロップは、ブレイキンの要素を持つブレイキン・床回転系の技です。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。レベル6「小技発展」では「以下の技から6個クリアで合格」が目安です。床支持の形、重心移動、回転の継続を安全に作ることが練習の中心です。 ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。 前提技・派生技・近い技は相関図で確認できます。', 'コインドロップの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。ブレイキン由来の動きは、床との接点、重心移動、回転の質感が特徴です。縄内ではロープに触れない低さと幅を把握します。床支持と重心移動を使って回転やフリーズ感を作る系統です。縄との距離、床に置く面、回転幅の管理が大切です。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['痛みがある日は無理に通さない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。ブレイキン・床回転系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 3, 3, 'ブレイキン', 'ブレイキン・床回転', '床回転', '手支持・床支持', '床・背中', '縄内単発', array['ブレイキン', 'ブレイキン・床回転', 'Lv.6'], 6, '小技発展', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
