insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000095', 't095', 'エアリアルツイスト', array[]::text[], 'トリッキング / ひねりの演技に入れやすい発展技。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。', 'エアリアルツイストは、トリッキングの要素を持つひねり系の技です。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。レベル8「空中系応用」では「以下の技から3個クリアで合格」が目安です。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', 'エアリアルツイストの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。ひねり系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 4, 4, 'トリッキング', 'ひねり', 'ひねり軸', 'その場', '足立ち', 'パフォーマンス', array['トリッキング', 'ひねり', 'Lv.8'], 8, '空中系応用', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
