insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000100', 't100', 'ムーンキック', array[]::text[], 'トリッキング / トリッキングの演技に入れやすい発展技。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。', 'ムーンキックは、トリッキングの要素を持つトリッキング系の技です。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。レベル8「空中系応用」では「以下の技から3個クリアで合格」が目安です。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', 'ムーンキックの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。トリッキング系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 4, 4, 'トリッキング', 'トリッキング', '移動・切り返し', 'その場', '足立ち', 'パフォーマンス', array['トリッキング', 'トリッキング', 'Lv.8'], 8, '空中系応用', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
