insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000109', 't109', '逆宙', array[]::text[], '体操 / 空中回転の演技に入れやすい発展技。踏切の高さ、回転姿勢、着地の向きを分けて確認しながら段階的に練習します。', '逆宙は、体操の要素を持つ空中回転系の技です。踏切で高さを作り、空中で姿勢をまとめ、着地でほどく系統です。縄内では回転そのものより入るタイミングと抜ける余白が重要です。レベル8「空中系応用」では「以下の技から3個クリアで合格」が目安です。踏切の高さ、回転姿勢、着地の向きを分けて確認しながら段階的に練習します。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '逆宙の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。踏切で高さを作り、空中で姿勢をまとめ、着地でほどく系統です。縄内では回転そのものより入るタイミングと抜ける余白が重要です。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。空中回転系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 4, 4, '体操', '空中回転', '縦・横回転', '助走・反発', '足立ち', 'パフォーマンス', array['体操', '空中回転', 'Lv.8'], 8, '空中系応用', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000110', 't110', 'コークスクリュー', array[]::text[], 'トリッキング / ひねりの十分な前提技が必要な高難度技。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。', 'コークスクリューは、トリッキングの要素を持つひねり系の技です。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。レベル9「空中回転1回ひねり」では「以下の技から2個クリアで合格」が目安です。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', 'コークスクリューの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。ひねり系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 5, 5, 'トリッキング', 'ひねり', 'ひねり軸', '片足', '足立ち', 'パフォーマンス', array['トリッキング', 'ひねり', 'Lv.9'], 9, '空中回転1回ひねり', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000111', 't111', 'トリプルフラッシュキック', array[]::text[], 'トリッキング / トリッキングの十分な前提技が必要な高難度技。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。', 'トリプルフラッシュキックは、トリッキングの要素を持つトリッキング系の技です。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。レベル9「空中回転1回ひねり」では「以下の技から2個クリアで合格」が目安です。片足踏切や斜めの軌道を使うので、入り方と着地後の流れまでセットで見ます。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', 'トリプルフラッシュキックの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。蹴り、片足踏切、斜め軌道を使って見せ方を作る系統です。技単体だけでなく、入り方と着地後の流れで印象が変わります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。トリッキング系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 5, 5, 'トリッキング', 'トリッキング', '移動・切り返し', 'その場', '足立ち', 'パフォーマンス', array['トリッキング', 'トリッキング', 'Lv.9'], 9, '空中回転1回ひねり', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = exclude