insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000125', 't125', 'オリジナル技', array[]::text[], 'その他 / 連続・創作の十分な前提技が必要な高難度技。単体技の完成度を保ったまま、つなぎ方と見せ方を設計します。', 'オリジナル技は、その他の要素を持つ連続・創作系の技です。複数の技を順番、向き、音取りで組み合わせる系統です。個々の成功率だけでなく、つなぎのロスを減らすことが中心になります。レベル10「空中回転1回ひねり＋α」では「以下の技から2個クリアで合格」が目安です。単体技の完成度を保ったまま、つなぎ方と見せ方を設計します。 複数ジャンルの身体操作を、ダブルダッチの演技に使いやすい形で整理しています。 前提技・派生技・近い技は相関図で確認できます。', 'オリジナル技の厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。複数ジャンルの身体操作を、ダブルダッチの演技に使いやすい形で整理しています。複数の技を順番、向き、音取りで組み合わせる系統です。個々の成功率だけでなく、つなぎのロスを減らすことが中心になります。', array['縄なしで形を確認する', '低速でタイミングを合わせる', '相関図で前提技と派生技を確認する'], array['入りのタイミングが毎回変わる', '成功後の抜け方まで決めていない'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', 'ターン側と入る位置を共有してから練習する'], '監修メモ未設定。連続・創作系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 5, 5, 'その他', '連続・創作', '移動・切り返し', 'その場', '足立ち', 'パフォーマンス', array['その他', '連続・創作', 'Lv.10'], 10, '空中回転1回ひねり＋α', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000126', 't126-15', '1.5回ひねり', array[]::text[], '体操 / ひねりの十分な前提技が必要な高難度技。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。', '1.5回ひねりは、体操の要素を持つひねり系の技です。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。レベル10「空中回転1回ひねり＋α」では「以下の技から2個クリアで合格」が目安です。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。 体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。 前提技・派生技・近い技は相関図で確認できます。', '1.5回ひねりの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。体操由来の動きは、姿勢、反発、着地の再現性が強みです。縄内では助走距離と着地後の抜け方を短く設計します。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。ひねり系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 5, 5, '体操', 'ひねり', 'ひねり軸', 'その場', '足立ち', 'パフォーマンス', array['体操', 'ひねり', 'Lv.10'], 10, '空中回転1回ひねり＋α', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
insert into public.tricks (id, slug, name, aliases, summary, description, origin_note, practice_steps, common_mistakes, safety_notes, coach_comment, knowledge_status, knowledge_reviewed_by, knowledge_source_urls, show_knowledge_sources, difficulty, risk_level, discipline, family, axis, takeoff, landing, rope_context, tags, level, level_category, status, source_id, show_source) values ('00000000-0000-4000-9000-000000000127', 't127', 'フルハイパー', array[]::text[], 'トリッキング / ひねりの十分な前提技が必要な高難度技。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。', 'フルハイパーは、トリッキングの要素を持つひねり系の技です。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。レベル10「空中回転1回ひねり＋α」では「以下の技から2個クリアで合格」が目安です。回転にひねりを加えるため、目線、締め、着地方向を前提技で確認してから扱います。 トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。 前提技・派生技・近い技は相関図で確認できます。', 'フルハイパーの厳密な発祥・初出は監修時に追記します。現時点では、技名の由来を断定するよりも、どのジャンルの身体操作として読み解けるかを優先して整理しています。トリッキング由来の動きは、蹴り足、斜め軌道、ひねりの見せ方が特徴です。縄内では入りのステップを整理すると扱いやすくなります。縦回転や横回転に肩、目線、骨盤の向きを加える発展系統です。高さを失わずにひねり始める順番を管理します。', array['踏切だけを分けて高さを作る', '補助やマットで回転姿勢を確認する', '着地方向を決めてから縄内のタイミングに合わせる'], array['踏切前に急いで高さが出ない', '着地を見る前に体をほどいてしまう'], array['初回は補助者とマットを用意する', '疲労時は回転量やひねり量を増やさない', '着地点の周囲とロープ位置を確認してから入る'], '監修メモ未設定。ひねり系として、成功条件・補助方法・縄内での注意点を監修後に追記してください。', 'draft', '', array[]::text[], false, 5, 5, 'トリッキング', 'ひねり', 'ひねり軸', 'その場', '足立ち', 'パフォーマンス', array['トリッキング', 'ひねり', 'Lv.10'], 10, '空中回転1回ひねり＋α', 'published', '00000000-0000-4000-8000-000000000001', false) on conflict (slug) do update set summary = excluded.summary, description = excluded.description, origin_note = excluded.origin_note, practice_steps = excluded.practice_steps, common_mistakes = excluded.common_mistakes, safety_notes = excluded.safety_notes, coach_comment = excluded.coach_comment, difficulty = excluded.difficulty, risk_level = excluded.risk_level, discipline = excluded.discipline, family = excluded.family, axis = excluded.axis, takeoff = excluded.takeoff, landing = excluded.landing, rope_context = excluded.rope_context, tags = excluded.tags, level = excluded.level, level_category = excluded.level_category, status = excluded.status, source_id = excluded.source_id;
